typedef enum fixture_case {
    FIXTURE_CASE_SUCCESS = 0,
    FIXTURE_CASE_SETUP_FAIL,
    FIXTURE_CASE_SETUP_SKIP,
    FIXTURE_CASE_BODY_FAIL,
    FIXTURE_CASE_TEARDOWN_FAIL,
    FIXTURE_CASE_TEARDOWN_SKIP
} fixture_case_t;

static fixture_case_t fixture_case = FIXTURE_CASE_SUCCESS;
static int fixture_setup_calls = 0;
static int fixture_body_calls = 0;
static int fixture_teardown_calls = 0;
static char fixture_order[8];
static int fixture_order_len = 0;

static void fixture_reset_log(void) {
    fixture_setup_calls = 0;
    fixture_body_calls = 0;
    fixture_teardown_calls = 0;
    fixture_order_len = 0;
    memset(fixture_order, 0, sizeof(fixture_order));
}

static void fixture_log_step(char step) {
    if (fixture_order_len < (int)sizeof(fixture_order) - 1) {
        fixture_order[fixture_order_len++] = step;
        fixture_order[fixture_order_len] = '\0';
    }
}

static void fixture_setup(void) {
    fixture_setup_calls++;
    fixture_log_step('S');
    if (fixture_case == FIXTURE_CASE_SETUP_FAIL) {
        MTEST_FAIL("fixture setup failure");
    }
    if (fixture_case == FIXTURE_CASE_SETUP_SKIP) {
        MTEST_SKIP("fixture setup skip");
    }
}

static void fixture_teardown(void) {
    fixture_teardown_calls++;
    fixture_log_step('T');
    if (fixture_case == FIXTURE_CASE_TEARDOWN_FAIL) {
        MTEST_FAIL("fixture teardown failure");
    }
    if (fixture_case == FIXTURE_CASE_TEARDOWN_SKIP) {
        MTEST_SKIP("fixture teardown skip");
    }
}

MTEST(fixture_contract_body) {
    fixture_body_calls++;
    fixture_log_step('B');
    if (fixture_case == FIXTURE_CASE_BODY_FAIL) {
        MTEST_ASSERT_EQ(1, 2);
    }
    MTEST_ASSERT_TRUE(1);
}

MTEST_SUITE(fixture_contract) {
    MTEST_RUN_F(fixture_contract_body, fixture_setup, fixture_teardown);
}

static int run_fixture_case_probe(fixture_case_t case_id,
                                  const char *expected_order,
                                  int expected_passed,
                                  int expected_failed,
                                  int expected_skipped,
                                  int expected_asserts_total,
                                  int expected_asserts_failed) {
    int ok = 1;
    mtest_state_t saved = mtest_g;

    fixture_case = case_id;
    fixture_reset_log();
    memset(&mtest_g, 0, sizeof(mtest_g));

    MTEST_SUITE_RUN(fixture_contract);

    if (mtest_g.tests_discovered != 1 ||
        mtest_g.tests_selected != 1 ||
        mtest_g.tests_run != 1 ||
        mtest_g.tests_passed != expected_passed ||
        mtest_g.tests_failed != expected_failed ||
        mtest_g.tests_skipped != expected_skipped ||
        mtest_g.tests_filtered_out != 0 ||
        mtest_g.suites_entered != 1 ||
        mtest_g.asserts_total != expected_asserts_total ||
        mtest_g.asserts_failed != expected_asserts_failed ||
        mtest_g.tests_passed + mtest_g.tests_failed + mtest_g.tests_skipped != mtest_g.tests_run ||
        mtest_g.tests_selected != mtest_g.tests_run ||
        mtest_g.tests_discovered != mtest_g.tests_selected + mtest_g.tests_filtered_out) {
        fprintf(stderr, "fixture lifecycle counter mismatch for case %d\n", (int)case_id);
        ok = 0;
    }

    if (fixture_setup_calls != 1 ||
        fixture_teardown_calls != 1 ||
        fixture_order_len != (int)strlen(expected_order) ||
        strcmp(fixture_order, expected_order) != 0) {
        fprintf(stderr, "fixture lifecycle call order mismatch for case %d\n", (int)case_id);
        ok = 0;
    }

    if (case_id == FIXTURE_CASE_SETUP_FAIL || case_id == FIXTURE_CASE_SETUP_SKIP) {
        if (fixture_body_calls != 0) {
            fprintf(stderr, "fixture body ran unexpectedly for case %d\n", (int)case_id);
            ok = 0;
        }
    } else if (fixture_body_calls != 1) {
        fprintf(stderr, "fixture body call count mismatch for case %d\n", (int)case_id);
        ok = 0;
    }

    if (mtest_g.current_test != NULL ||
        mtest_g.current_suite != NULL ||
        mtest_g.current_skip_reason != NULL ||
        mtest_g.current_outcome != MTEST_OUTCOME_NOT_RUN ||
        mtest_g.current_phase != MTEST_PHASE_IDLE ||
        mtest_g.current_failed != 0) {
        fprintf(stderr, "fixture lifecycle left runner dirty for case %d\n", (int)case_id);
        ok = 0;
    }

    mtest_g = saved;
    return ok;
}

static int run_fixture_lifecycle_probe(void) {
    int ok = 1;

    if (!run_fixture_case_probe(FIXTURE_CASE_SUCCESS, "SBT", 1, 0, 0, 1, 0)) {
        ok = 0;
    }
    if (!run_fixture_case_probe(FIXTURE_CASE_SETUP_FAIL, "ST", 0, 1, 0, 0, 1)) {
        ok = 0;
    }
    if (!run_fixture_case_probe(FIXTURE_CASE_SETUP_SKIP, "ST", 0, 0, 1, 0, 0)) {
        ok = 0;
    }
    if (!run_fixture_case_probe(FIXTURE_CASE_BODY_FAIL, "SBT", 0, 1, 0, 1, 1)) {
        ok = 0;
    }
    if (!run_fixture_case_probe(FIXTURE_CASE_TEARDOWN_FAIL, "SBT", 0, 1, 0, 1, 1)) {
        ok = 0;
    }
    if (!run_fixture_case_probe(FIXTURE_CASE_TEARDOWN_SKIP, "SBT", 0, 1, 0, 1, 0)) {
        ok = 0;
    }

    return ok;
}

typedef struct {
    int a;
    int b;
    int c;
} assertion_eval_state_t;

static assertion_eval_state_t assertion_eval_state = {0, 0, 0};

static void assertion_eval_reset(void) {
    assertion_eval_state.a = 0;
    assertion_eval_state.b = 0;
    assertion_eval_state.c = 0;
}

static int assertion_eval_a_int(int value) {
    assertion_eval_state.a++;
    return value;
}

static int assertion_eval_b_int(int value) {
    assertion_eval_state.b++;
    return value;
}

static int assertion_eval_c_int(int value) {
    assertion_eval_state.c++;
    return value;
}

static void *assertion_eval_a_ptr(void *value) {
    assertion_eval_state.a++;
    return value;
}

static const char *assertion_eval_a_str(const char *value) {
    assertion_eval_state.a++;
    return value;
}

static const char *assertion_eval_b_str(const char *value) {
    assertion_eval_state.b++;
    return value;
}

static const unsigned char *assertion_eval_a_mem(const unsigned char *value) {
    assertion_eval_state.a++;
    return value;
}

static const unsigned char *assertion_eval_b_mem(const unsigned char *value) {
    assertion_eval_state.b++;
    return value;
}

#if MTEST_ENABLE_FLOAT

static float assertion_eval_a_float(float value) {
    assertion_eval_state.a++;
    return value;
}

static float assertion_eval_b_float(float value) {
    assertion_eval_state.b++;
    return value;
}

static double assertion_eval_a_double(double value) {
    assertion_eval_state.a++;
    return value;
}

static double assertion_eval_b_double(double value) {
    assertion_eval_state.b++;
    return value;
}

#endif

static size_t assertion_eval_c_size(size_t value) {
    assertion_eval_state.c++;
    return value;
}

typedef void (*assertion_probe_fn_t)(void);

#define ASSERTION_CASE(name, body) static void name(void) { body }

static int assertion_eval_counts_match(int expected_a,
                                       int expected_b,
                                       int expected_c) {
    return assertion_eval_state.a == expected_a &&
           assertion_eval_state.b == expected_b &&
           assertion_eval_state.c == expected_c;
}

