#if defined(_MSC_VER)
#pragma warning(pop)
#endif

int main(int argc, char **argv) {
    mtest_begin_result_t begin_result = MTEST_BEGIN(argc, argv);
    if (begin_result == MTEST_BEGIN_HELP_REQUESTED) {
        return 0;
    }
    if (begin_result == MTEST_BEGIN_INVALID_ARGUMENT) {
        return 1;
    }

    MTEST_SUITE_RUN(integers);
    MTEST_SUITE_RUN(booleans);
    MTEST_SUITE_RUN(pointers);
    MTEST_SUITE_RUN(strings);
    MTEST_SUITE_RUN(memory);
#if MTEST_ENABLE_FLOAT
    MTEST_SUITE_RUN(floats);
#endif
    MTEST_SUITE_RUN(fixtures);
    MTEST_SUITE_RUN(misc);
    if (mtest_g.filter == NULL && !mtest_g.list_only && !mtest_g.stop_on_fail) {
        if (!run_string_memory_pointer_safety_probe()) {
            return 1;
        }
    }
    if (mtest_g.filter == NULL && !mtest_g.list_only && !mtest_g.stop_on_fail) {
        if (!run_typed_integer_boundary_probe()) {
            return 1;
        }
    }
    if (mtest_g.filter == NULL && !mtest_g.list_only && !mtest_g.stop_on_fail) {
        if (!run_assertion_single_eval_probe()) {
            return 1;
        }
    }
    if (mtest_g.filter == NULL && !mtest_g.list_only && !mtest_g.stop_on_fail) {
        if (!run_fixture_lifecycle_probe()) {
            return 1;
        }
    }
    if (mtest_g.filter == NULL && !mtest_g.list_only && !mtest_g.stop_on_fail) {
        if (!run_counter_contract_probe()) {
            return 1;
        }
    }

    /* Verify setup/teardown was called (only when not filtering) */
    if (mtest_g.filter == NULL && !mtest_g.list_only) {
        if (setup_called != 1 || teardown_called != 1) {
            printf("  FIXTURE ERROR: setup=%d teardown=%d\n",
                   setup_called, teardown_called);
            mtest_g.tests_failed++;
        }
    }

    return MTEST_END();
}
